// Opt-in integration: real Vue components + loopback Gin/Huma synthetic fixture.
// PLAYWRIGHT_MODULE may point to an isolated test-only installation.
import assert from "node:assert/strict";
import { mkdir } from "node:fs/promises";
const { chromium } = await import(process.env.PLAYWRIGHT_MODULE || "playwright");
assert.ok(process.env.SKILL_TOOLS_CDP?.startsWith("ws://127.0.0.1:"), "isolated loopback CDP required");
const browser = await chromium.connectOverCDP(process.env.SKILL_TOOLS_CDP);
const page = browser.contexts()[0].pages()[0];
const evidence = process.env.SKILL_TOOLS_EVIDENCE || "/tmp/skill-tools-v2-evidence";
await mkdir(evidence, { recursive: true });
const errors = [], requests = [], checks = [];
page.on("pageerror", error => errors.push(error.message));
page.on("console", message => { if (message.type() === "error") errors.push(message.text()); });
page.on("request", request => {
  const url = new URL(request.url());
  if (url.pathname.startsWith("/api/")) requests.push({ method: request.method(), path: url.pathname, query: url.search });
});
const passed = name => { checks.push(name); console.log(`PASS ${name}`); };
const get = path => page.request.get(new URL(path, page.url()).href);
const poll = async (fn, message) => {
  const until = Date.now() + 15000;
  while (Date.now() < until) { if (await fn()) return; await new Promise(resolve => setTimeout(resolve, 30)); }
  throw new Error(message);
};
const next = scope => scope.getByRole("button", { name: "下一页", exact: true });
const prev = scope => scope.getByRole("button", { name: "上一页", exact: true });
const pager = scope => scope.locator(".collection-pager").last();
const onPage = async (scope, number, total) => poll(async () =>
  (await pager(scope).innerText()).includes(`${number} · ${total}`), `page ${number}/${total}`);
const noOverflow = async () => {
  const metrics = await page.evaluate(() => ({ width: innerWidth, scroll: document.documentElement.scrollWidth }));
  assert.ok(metrics.scroll <= metrics.width + 1, `horizontal overflow: ${JSON.stringify(metrics)}`);
};
try {
  await page.setViewportSize({ width: 1440, height: 1000 });
  await page.goto("http://127.0.0.1:18882/tests/fixtures/skill-tools.html");
  const skills = page.locator(".skills-view");
  await onPage(skills, 1, 65);
  await next(pager(skills)).click(); await onPage(skills, 2, 65);
  await next(pager(skills)).click(); await onPage(skills, 3, 65);
  assert.equal(await skills.locator(".skill-card").count(), 20);
  assert.equal(await skills.locator(".skill-name").first().textContent(), "Synthetic skill 41");
  const search = skills.locator(".list-search");
  await search.fill("Synthetic"); await onPage(skills, 1, 65);
  await next(pager(skills)).click(); await onPage(skills, 2, 65);
  await next(pager(skills)).click(); await onPage(skills, 3, 65);
  assert.ok(requests.some(r => r.query.includes("page=3") && r.query.includes("search=Synthetic")));
  passed("management skills/search use three real backend pages");

  // Delayed old response must not replace a newer query.
  await search.fill("slow");
  await poll(() => requests.some(r => r.query.includes("search=slow")), "slow request started");
  await search.fill("fixture-skill-01");
  await onPage(skills, 1, 1);
  await new Promise(resolve => setTimeout(resolve, 950));
  assert.equal(await skills.locator(".skill-name").textContent(), "Synthetic skill 01");
  passed("out-of-order search response fenced");

  await skills.getByRole("button", { name: "绑定工具", exact: true }).click();
  let relations = skills.locator(".relations");
  await onPage(relations, 1, 45);
  await relations.getByRole("checkbox").first().uncheck();
  const writesBeforeDiscard = requests.filter(r => r.method === "PATCH").length;
  await relations.getByRole("button", { name: "取消更改", exact: true }).click();
  assert.match(await relations.innerText(), /待保存 0/);
  assert.equal(requests.filter(r => r.method === "PATCH").length, writesBeforeDiscard);
  await relations.getByRole("checkbox").first().uncheck();
  await next(pager(relations)).click(); await onPage(relations, 2, 45);
  await next(pager(relations)).click(); await onPage(relations, 3, 45);
  await relations.getByRole("checkbox").first().uncheck();
  assert.match(await relations.innerText(), /待保存 2/);
  await relations.getByRole("button", { name: "重新加载", exact: true }).click();
  await onPage(relations, 3, 45);
  assert.match(await relations.innerText(), /待保存 2/);
  await relations.getByRole("button", { name: "保存", exact: true }).click();
  await onPage(relations, 3, 43);
  const bound = await get("/api/v1/addons/tool?skillId=1&bound=yes&page=1&pageSize=100");
  const boundBody = await bound.json();
  assert.equal(boundBody.total, 43);
  assert.ok(!boundBody.data.some(row => row.id === 1 || row.id === 41));
  await relations.getByRole("button", { name: "可绑定", exact: true }).click();
  await onPage(relations, 1, 22);
  const candidates = relations.getByRole("checkbox");
  await candidates.nth(0).check(); await candidates.nth(1).check();
  await relations.getByRole("button", { name: "保存", exact: true }).click();
  await onPage(relations, 1, 20);
  passed("cross-page unlink and inline rebind persist both IDs");

  await skills.getByRole("button", { name: "文件", exact: true }).click();
  const drawer = page.locator(".drawer");
  await drawer.getByRole("button", { name: "docs", exact: true }).click();
  await onPage(drawer, 1, 65);
  await next(pager(drawer)).click(); await onPage(drawer, 2, 65);
  await next(pager(drawer)).click(); await onPage(drawer, 3, 65);
  await drawer.getByRole("button", { name: "file-40.md", exact: true }).click();
  await poll(async () => (await drawer.locator(".content-pre").textContent())?.includes("Synthetic file"), "file preview");
  await drawer.getByRole("searchbox").fill("file-"); await onPage(drawer, 1, 65);
  await next(pager(drawer)).click(); await onPage(drawer, 2, 65);
  await next(pager(drawer)).click(); await onPage(drawer, 3, 65);
  await page.screenshot({ path: `${evidence}/files-1440.png` });
  await drawer.getByRole("button", { name: "关闭", exact: true }).click();
  passed("archive directory and search pages plus real file preview");

  await page.getByRole("button", { name: "tools", exact: true }).click();
  const tools = page.locator(".tools-view");
  await onPage(tools, 1, 65);
  await next(pager(tools)).click(); await onPage(tools, 2, 65);
  await next(pager(tools)).click(); await onPage(tools, 3, 65);
  await tools.locator(".list-header input").fill("Synthetic"); await onPage(tools, 1, 65);
  await next(pager(tools)).click(); await onPage(tools, 2, 65);
  await next(pager(tools)).click(); await onPage(tools, 3, 65);
  await tools.locator(".list-header input").fill("fixture-tool-01"); await onPage(tools, 1, 1);
  await tools.getByRole("button", { name: "引用技能", exact: true }).click();
  relations = tools.locator(".relations");
  await onPage(relations, 1, 45);
  await next(pager(relations)).click(); await onPage(relations, 2, 45);
  await next(pager(relations)).click(); await onPage(relations, 3, 45);
  await relations.getByRole("searchbox").fill("Synthetic"); await onPage(relations, 1, 45);
  await next(pager(relations)).click(); await onPage(relations, 2, 45);
  await next(pager(relations)).click(); await onPage(relations, 3, 45);
  passed("tools management/search and reverse-reference search have three pages");

  await tools.locator(".list-header .btn-primary").click();
  let dialog = page.locator(".modal-card");
  assert.equal(await dialog.locator(".switch-row input").isChecked(), true);
  await dialog.locator(".field input").nth(0).fill("Synthetic created tool");
  await dialog.locator(".field input").nth(1).fill("synthetic-created-tool");
  await dialog.locator(".field input").nth(2).fill("https://fixture.invalid/mcp");
  await onPage(dialog, 1, 65);
  await dialog.locator(".check-row input").first().check();
  await next(pager(dialog)).click(); await onPage(dialog, 2, 65);
  await next(pager(dialog)).click(); await onPage(dialog, 3, 65);
  await dialog.locator(".check-row input").first().check();
  await page.screenshot({ path: `${evidence}/create-tool-1440.png` });
  await dialog.locator(".modal-footer .btn-primary").click();
  await poll(async () => await dialog.count() === 0, "created tool dialog closed");
  await onPage(tools.locator(".relations"), 1, 2);
  assert.equal(await tools.locator(".tool-name").textContent(), "Synthetic created tool");
  assert.equal(await tools.locator(".badge").textContent(), "已启用");
  const createdTool = (await (await get("/api/v1/addons/tool?search=synthetic-created-tool")).json()).data[0];
  assert.equal(createdTool.isActive, true);
  const disabledTool = (await (await get("/api/v1/addons/tool?ids=65")).json()).data[0];
  assert.equal(disabledTool.isActive, false);
  await tools.getByRole("button", { name: "编辑", exact: true }).click();
  const editor = page.locator(".definition-drawer");
  await poll(async () => (await editor.locator("h2").textContent()) === createdTool.name, "created tool detail");
  assert.equal(await editor.locator(".tool-field").filter({ hasText: "/isActive" }).getByRole("checkbox").isChecked(), true);
  await editor.getByRole("button", { name: "关闭", exact: true }).click();
  passed("new tool default true, cross-page initial skills, no revival of disabled tool");

  await tools.locator(".probe-form input").fill("http://127.0.0.1:18881/fixture/mcp");
  await tools.locator(".probe-form button").click();
  const probe = tools.locator(".probe-results");
  await onPage(probe, 1, 70);
  await probe.getByRole("checkbox").first().check();
  await next(pager(probe)).click(); await onPage(probe, 2, 70);
  await next(pager(probe)).click(); await onPage(probe, 3, 70);
  await probe.getByRole("checkbox").first().check();
  await probe.getByRole("searchbox").fill("fixture_probe"); await onPage(probe, 1, 70);
  await next(pager(probe)).click(); await onPage(probe, 2, 70);
  await next(pager(probe)).click(); await onPage(probe, 3, 70);
  await probe.locator(".probe-results-head button").click();
  await poll(async () => (await probe.locator(".probe-results-head button").textContent()).includes("0"), "import cross-page choices");
  const imports = await (await get("/api/v1/addons/tool?search=fixture_probe")).json();
  assert.deepEqual(imports.data.map(row => row.slug).sort(), ["fixture_probe_00", "fixture_probe_40"]);
  assert.ok(imports.data.every(row => row.isActive && !row.config?.mcp_config?.input_schema));
  passed("70 MCP candidates with cursor/search pages and cross-page import without invented schema");

  await page.getByRole("button", { name: "skills", exact: true }).click();
  await onPage(skills, 1, 65);
  await skills.getByRole("button", { name: "新建技能", exact: true }).click();
  dialog = page.locator(".create-dialog");
  await dialog.getByLabel("名称", { exact: true }).fill("Synthetic created skill");
  await dialog.getByLabel("标识", { exact: true }).fill("synthetic-created-skill");
  await dialog.getByLabel("描述", { exact: true }).fill("Synthetic description");
  await dialog.getByLabel("技能指令", { exact: true }).fill("Do not call business tools.");
  await onPage(dialog, 1, 68);
  await dialog.locator("section input[type=checkbox]").first().check();
  await next(pager(dialog)).click(); await onPage(dialog, 2, 68);
  await next(pager(dialog)).click(); await onPage(dialog, 3, 68);
  await dialog.locator("section input[type=checkbox]").first().check();
  await page.setViewportSize({ width: 390, height: 844 });
  await noOverflow();
  await poll(async () => await page.locator('body > div[style*="pointer-events: none"] > div').count() === 0, "transient notices expire");
  await page.screenshot({ path: `${evidence}/create-skill-390.png` });
  await dialog.getByRole("button", { name: "保存", exact: true }).click();
  await poll(async () => await dialog.count() === 0, "created skill dialog closed");
  await onPage(skills.locator(".relations"), 1, 2);
  assert.equal(await skills.locator(".skill-name").textContent(), "Synthetic created skill");
  await noOverflow();
  await page.screenshot({ path: `${evidence}/created-skill-390.png` });
  await skills.getByRole("button", { name: "文件", exact: true }).click();
  await drawer.getByRole("button", { name: "SKILL.md", exact: true }).click();
  await poll(async () => (await drawer.locator(".content-pre").textContent())?.includes("Do not call business tools."), "created artifact preview");
  await drawer.getByRole("button", { name: "关闭", exact: true }).click();
  passed("new skill with real artifact and cross-page initial tools, narrow viewport");

  await page.getByRole("button", { name: "conversation", exact: true }).click();
  await page.getByTestId("skill-picker-open").click();
  const sheet = page.locator(".osheet");
  await onPage(sheet, 1, 66);
  await sheet.locator(".osheet-row").first().click();
  await next(pager(sheet)).click(); await onPage(sheet, 2, 66);
  await next(pager(sheet)).click(); await onPage(sheet, 3, 66);
  await sheet.locator(".osheet-row").first().click();
  await sheet.getByRole("searchbox").fill("Synthetic"); await onPage(sheet, 1, 66);
  await next(pager(sheet)).click(); await onPage(sheet, 2, 66);
  await next(pager(sheet)).click(); await onPage(sheet, 3, 66);
  await noOverflow();
  await page.screenshot({ path: `${evidence}/conversation-skills-390.png` });
  await sheet.getByRole("button", { name: "完成", exact: true }).click();
  assert.equal(await page.locator(".skill-chip").count(), 2);
  await page.getByTestId("tool-picker-open").click();
  await onPage(sheet, 1, 67);
  await next(pager(sheet)).click(); await onPage(sheet, 2, 67);
  await next(pager(sheet)).click(); await onPage(sheet, 3, 67);
  await sheet.getByRole("searchbox").fill("Synthetic"); await onPage(sheet, 1, 67);
  await next(pager(sheet)).click(); await onPage(sheet, 2, 67);
  await next(pager(sheet)).click(); await onPage(sheet, 3, 67);
  await page.screenshot({ path: `${evidence}/conversation-tools-390.png` });
  passed("conversation skill/tool sheets and search page on server, choices survive pages");
  await sheet.getByRole("button", { name: "完成", exact: true }).click();
  await page.getByRole("button", { name: "tools", exact: true }).click();
  await onPage(tools, 1, 68);
  await noOverflow(); await page.screenshot({ path: `${evidence}/tools-390.png` });
  await page.setViewportSize({ width: 1440, height: 1000 });
  await noOverflow(); await page.screenshot({ path: `${evidence}/tools-1440.png` });
  assert.deepEqual(errors, [], "browser console/page errors");
  passed("390/1440 screenshots, no horizontal overflow or console errors");
  console.log(JSON.stringify({ checks: checks.length, requests: requests.length,
    page3Requests: requests.filter(r => r.query.includes("page=3")).length, errors }, null, 2));
} finally {
  // Disconnect only; the isolated agent-browser session is cleaned up by its owner.
  await browser.close();
}
